#include "shell/form_bridge.hpp"
#include "support/check.hpp"
using namespace squiflow;app::RequestContext ctx(){return app::RequestContext::create({engine::RecordId{1,1}},engine::PersonId{2,2},{},"form",1).value();}
int main(){namespace t=testing;using namespace shell;std::vector<FormFieldSpec>s={{"name","name",FormFieldKind::Text,true},{"amount","amount",FormFieldKind::MoneyMinor,true,0,100000,true},{"due","due",FormFieldKind::Date,true}};FormBridge f(s,ctx());t::check(f.set("name","Desk")&&f.set("amount","12.34")&&f.set("due","2026-08-06"),"draft accepts presentation strings");auto q=f.begin_submit();t::check(q&&q.value().values[1].value=="1234"&&f.pending(),"money becomes exact minor units");t::check(!f.begin_submit(),"double submit refused");auto g=q.value().generation;f.cancel();t::check(!f.complete(g,app::Result<std::string,app::DomainError>::success("late")),"cancel makes completion stale");f.set("amount","12.345");t::check(!f.begin_submit()&&!f.field_errors().empty(),"malformed money is field error");f.set("amount","12.34");q=f.begin_submit();f.complete(q.value().generation,app::Result<std::string,app::DomainError>::failure({app::DomainErrorCode::Conflict,"taken","name"}));t::check(!f.pending()&&f.dirty()&&f.field_errors()[0].field=="name","domain rejection restores editable field error");for(auto c:{app::DomainErrorCode::NotFound,app::DomainErrorCode::Unauthorized,app::DomainErrorCode::ValidationFailed,app::DomainErrorCode::Conflict,app::DomainErrorCode::Offline,app::DomainErrorCode::Timeout,app::DomainErrorCode::Cancelled,app::DomainErrorCode::InvalidContext})t::check(!domain_error_message(c).empty(),"every domain error mapped");return t::report();}
